function calcolaStraordinariConfigurati({
  giornateMese,
  tuttiTurni,
  modalita,
  sogliaGiornaliera,
  sogliaSettimanale,
  meseTarget,
  annoTarget,
  abilitaManuale = true,
}) {
  if (abilitaManuale && tuttiTurni.some(t => t.straordinario_manuale_minuti != null)) {
    const selezionati = new Set(giornateMese);
    return classificaTurniGpg(tuttiTurni, { modalita, sogliaGiornaliera, sogliaSettimanale })
      .filter(r => selezionati.has(r.turno))
      .reduce((tot, r) => tot + r.straordinarie, 0);
  }
  // MODALITÀ GIORNALIERA
  if (modalita !== 'settimanale') {
    const turniOrdinari = giornateMese.filter(
      (t) => t.riposo_lavorato !== true
    );

    return aggregaTurniPerGiorno(
      turniOrdinari,
      sogliaGiornaliera
    ).reduce(
      (tot, giorno) => tot + giorno.oreStraordinarie,
      0
    );
  }

  // MODALITÀ SETTIMANALE
  const limiteSettimanale =
    Number(sogliaSettimanale) > 0
      ? Number(sogliaSettimanale)
      : 40;

  const turniUtili = tuttiTurni
    .filter(
      (t) =>
        t.tipo === 'turno' &&
        t.riposo_lavorato !== true &&
        Number(t.ore || 0) > 0 &&
        Number(t.giorno) > 0 &&
        Number(t.mese) > 0 &&
        Number(t.anno) > 0
    )
    .map((t) => {
      const data = new Date(
        Number(t.anno),
        Number(t.mese) - 1,
        Number(t.giorno),
        12,
        0,
        0
      );

      const giornoSettimana = data.getDay();
      const distanzaLunedi =
        giornoSettimana === 0
          ? -6
          : 1 - giornoSettimana;

      const lunedi = new Date(data);
      lunedi.setDate(data.getDate() + distanzaLunedi);
      lunedi.setHours(0, 0, 0, 0);

      return {
        ...t,
        data,
        chiaveSettimana: [
          lunedi.getFullYear(),
          String(lunedi.getMonth() + 1).padStart(2, '0'),
          String(lunedi.getDate()).padStart(2, '0'),
        ].join('-'),
      };
    })
    .sort((a, b) => a.data - b.data);

  const settimane = {};

  turniUtili.forEach((t) => {
    if (!settimane[t.chiaveSettimana]) {
      settimane[t.chiaveSettimana] = [];
    }

    settimane[t.chiaveSettimana].push(t);
  });

  let extraMese = 0;

  Object.values(settimane).forEach((turniSettimana) => {
    let cumulato = 0;

    turniSettimana.forEach((t) => {
      const oreTurno =
        Number(t.ore || 0) +
        Number(t.minuti_aggiuntivi_retribuiti || 0) / 60;

      const extraPrima =
        Math.max(0, cumulato - limiteSettimanale);

      cumulato += oreTurno;

      const extraDopo =
        Math.max(0, cumulato - limiteSettimanale);

      const extraTurno =
        Math.max(0, extraDopo - extraPrima);

      if (
        Number(t.mese) === Number(meseTarget) &&
        Number(t.anno) === Number(annoTarget)
      ) {
        extraMese += extraTurno;
      }
    });
  });

  return extraMese;
}

